import sys
from types import ModuleType
from unittest.mock import MagicMock
import importlib

# The function from diffsettings.py
def module_to_dict(module, omittable=lambda k: k.startswith('_')):
    return {k: repr(v) for k, v in module.__dict__.items() if not omittable(k)}

def handle_diffsettings(user_settings_mod, global_settings_mod, options):
    # Mocking the logic in handle()
    # In real code, user_settings_mod would be settings._wrapped
    user_settings = module_to_dict(user_settings_mod)

    if options['default']:
        # Simulate importlib.import_module(options['default'])
        if options['default'] == 'settings.base':
            # Create a mock module for settings.base
            base_settings_dict = {'DEBUG': 'True', 'DATABASE': 'sqlite3', 'SECRET_KEY': 'xyz'}
            base_settings_mod = MagicMock(spec=ModuleType)
            base_settings_mod.__dict__ = base_settings_dict
            default_settings = module_to_dict(base_settings_mod)
        else:
            raise ImportError("No module named %s" % options['default'])
    else:
        default_settings = module_to_dict(global_settings_mod)

    output = []
    for key in sorted(user_settings):
        if key not in default_settings:
            output.append("%s = %s  ###" % (key, user_settings[key]))
        elif user_settings[key] != default_settings[key]:
            output.append("%s = %s" % (key, user_settings[key]))
        elif options['all']:
            output.append("### %s = %s" % (key, user_settings[key]))
    return '\n'.join(output)

# Setup
user_settings_dict = {'DEBUG': 'True', 'DATABASE': 'sqlite3', 'SECRET_KEY': 'abc'}
global_settings_dict = {'DEBUG': 'False', 'DATABASE': 'postgresql', 'SECRET_KEY': '123'}

user_settings_mod = MagicMock(spec=ModuleType)
user_settings_mod.__dict__ = user_settings_dict

global_settings_mod = MagicMock(spec=ModuleType)
global_settings_mod.__dict__ = global_settings_dict

# Test 1: Default behavior (no --default)
options = {'all': False, 'default': None}
print("Comparison with global_settings (no --default):")
print(handle_diffsettings(user_settings_mod, global_settings_mod, options))

# Test 2: With --default=settings.base
options = {'all': False, 'default': 'settings.base'}
print("\nComparison with settings.base (--default=settings.base):")
print(handle_diffsettings(user_settings_mod, global_settings_mod, options))
